"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";

type Filter = "전체" | "진행중" | "완료";

type Todo = {
  id: number;
  text: string;
  done: boolean;
  priority: "높음" | "보통" | "낮음";
};

function Toast({ message, type, onClose }: { message: string; type: "success" | "error" | "warning"; onClose: () => void }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);

  const colors = {
    success: "bg-green-500",
    error: "bg-red-500",
    warning: "bg-yellow-500",
  };

  return (
    <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-lg text-white text-sm font-medium shadow-lg ${colors[type]} flex items-center gap-3 z-50`}>
      {message}
      <button onClick={onClose} className="opacity-70 hover:opacity-100 text-xs">✕</button>
    </div>
  );
}

function ConfirmModal({ message, onConfirm, onCancel }: { message: string; onConfirm: () => void; onCancel: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/40" onClick={onCancel} />
      <div className="relative bg-white rounded-xl border border-zinc-200 p-6 w-72 flex flex-col gap-4 shadow-xl">
        <p className="text-sm text-zinc-700">{message}</p>
        <div className="flex gap-2 justify-end">
          <button onClick={onCancel} className="px-3 py-1.5 text-xs font-medium rounded-md border border-zinc-200 text-zinc-600 hover:bg-zinc-50">취소</button>
          <button onClick={onConfirm} className="px-3 py-1.5 text-xs font-medium rounded-md bg-red-500 text-white hover:bg-red-600">삭제</button>
        </div>
      </div>
    </div>
  );
}

const priorityColors: Record<string, string> = {
  높음: "bg-red-100 text-red-700",
  보통: "bg-blue-100 text-blue-700",
  낮음: "bg-zinc-100 text-zinc-500",
};

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([
    { id: 1, text: "디자인 시스템 색상 정의하기", done: false, priority: "높음" },
    { id: 2, text: "타이포그래피 스케일 설정", done: true, priority: "보통" },
    { id: 3, text: "버튼 컴포넌트 구현", done: false, priority: "낮음" },
  ]);
  const [input, setInput] = useState("");
  const [priority, setPriority] = useState<Todo["priority"]>("보통");
  const [filter, setFilter] = useState<Filter>("전체");
  const [showDone, setShowDone] = useState(true);
  const [modal, setModal] = useState<number | null>(null);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" | "warning" } | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  let nextId = useRef(4);

  const showToast = (message: string, type: "success" | "error" | "warning") => {
    setToast({ message, type });
  };

  const addTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) {
      showToast("할 일을 입력해주세요", "warning");
      return;
    }
    setTodos((t) => [...t, { id: nextId.current++, text: input.trim(), done: false, priority }]);
    setInput("");
    inputRef.current?.focus();
    showToast("추가됐어요", "success");
  };

  const toggleTodo = (id: number) => {
    setTodos((t) => t.map((x) => x.id === id ? { ...x, done: !x.done } : x));
  };

  const deleteTodo = (id: number) => {
    setTodos((t) => t.filter((x) => x.id !== id));
    setModal(null);
    showToast("삭제됐어요", "error");
  };

  const clearDone = () => {
    setTodos((t) => t.filter((x) => !x.done));
    showToast("완료된 항목을 모두 지웠어요", "success");
  };

  const filters: Filter[] = ["전체", "진행중", "완료"];

  const filtered = todos.filter((t) => {
    if (!showDone && t.done) return false;
    if (filter === "진행중") return !t.done;
    if (filter === "완료") return t.done;
    return true;
  });

  const doneCount = todos.filter((t) => t.done).length;

  return (
    <div className="min-h-screen bg-zinc-50 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-zinc-200 px-6 py-4 flex items-center justify-between">
        <span className="text-sm font-semibold tracking-tight">Vernacular</span>
        <Link href="/foundation/colors" className="px-3 py-1.5 text-xs font-medium rounded-md border border-zinc-200 text-zinc-600 hover:bg-zinc-50 transition-colors">
          디자인 시스템 보기 →
        </Link>
      </header>

      <main className="max-w-lg mx-auto px-4 py-10 flex flex-col gap-6">
        {/* Title + stats */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-semibold text-zinc-900">할 일 목록</h1>
            <p className="text-xs text-zinc-400 mt-0.5">{todos.length}개 중 {doneCount}개 완료</p>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-zinc-500">완료 표시</span>
            <button
              onClick={() => setShowDone(!showDone)}
              className={`w-9 h-5 rounded-full transition-colors ${showDone ? "bg-zinc-900" : "bg-zinc-200"}`}
            >
              <span className={`block w-3 h-3 bg-white rounded-full shadow transition-transform mx-1 ${showDone ? "translate-x-4" : "translate-x-0"}`} />
            </button>
          </div>
        </div>

        {/* Add form */}
        <div className="bg-white rounded-xl border border-zinc-200 p-4 flex flex-col gap-3">
          <form onSubmit={addTodo} className="flex gap-2">
            <input
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="flex-1 px-3 py-2 text-sm border border-zinc-200 rounded-md outline-none focus:ring-2 focus:ring-zinc-900 transition-all"
              placeholder="새로운 할 일 추가"
            />
            <button type="submit" className="px-4 py-2 text-sm font-medium rounded-md bg-zinc-900 text-white hover:bg-zinc-700 transition-colors shrink-0">
              추가
            </button>
          </form>
          <div className="flex gap-2">
            {(["높음", "보통", "낮음"] as const).map((p) => (
              <button
                key={p}
                onClick={() => setPriority(p)}
                className={`px-2.5 py-1 text-xs font-medium rounded-full transition-colors ${priority === p ? priorityColors[p] : "bg-zinc-100 text-zinc-400"}`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        {/* Filter nav */}
        <nav className="flex items-center gap-1 bg-white border border-zinc-200 rounded-lg p-1">
          {filters.map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 px-3 py-1.5 text-xs font-medium rounded-md transition-colors ${filter === f ? "bg-zinc-900 text-white" : "text-zinc-500 hover:text-zinc-900"}`}
            >
              {f}
              {f === "완료" && doneCount > 0 && (
                <span className="ml-1.5 px-1.5 py-0.5 rounded-full bg-white/20 text-[10px]">{doneCount}</span>
              )}
            </button>
          ))}
        </nav>

        {/* Todo list */}
        <div className="flex flex-col gap-2">
          {filtered.length === 0 && (
            <div className="bg-white rounded-xl border border-zinc-200 px-5 py-10 text-center text-sm text-zinc-400">
              할 일이 없어요
            </div>
          )}
          {filtered.map((todo) => (
            <div
              key={todo.id}
              className={`bg-white rounded-xl border border-zinc-200 px-4 py-3 flex items-center gap-3 transition-opacity ${todo.done ? "opacity-50" : ""}`}
            >
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleTodo(todo.id)}
                className="w-4 h-4 rounded accent-zinc-900 cursor-pointer shrink-0"
              />
              <span className={`flex-1 text-sm ${todo.done ? "line-through text-zinc-400" : "text-zinc-700"}`}>
                {todo.text}
              </span>
              <span className={`px-2 py-0.5 text-[10px] font-medium rounded-full shrink-0 ${priorityColors[todo.priority]}`}>
                {todo.priority}
              </span>
              <button
                onClick={() => setModal(todo.id)}
                className="text-zinc-300 hover:text-red-400 transition-colors text-xs shrink-0"
              >
                ✕
              </button>
            </div>
          ))}
        </div>

        {/* Clear done */}
        {doneCount > 0 && (
          <button
            onClick={clearDone}
            className="px-4 py-2 text-sm font-medium rounded-md border border-zinc-200 text-zinc-500 hover:bg-zinc-100 transition-colors w-full"
          >
            완료된 항목 모두 지우기 ({doneCount})
          </button>
        )}
      </main>

      {/* Modal */}
      {modal !== null && (
        <ConfirmModal
          message="이 항목을 삭제할까요?"
          onConfirm={() => deleteTodo(modal)}
          onCancel={() => setModal(null)}
        />
      )}

      {/* Toast */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </div>
  );
}

