import { useState, useRef, useEffect } from "react";
import Link from "next/link";

type Filter = "전체" | "진행중" | "완료";

type Todo = {
  id: number;
  text: string;
  done: boolean;
  priority: "높음" | "보통" | "낮음";
};

function Toast({ message, type, onClose }: { message: string; type: "success" | "error" | "warning"; onClose: () => void }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);

  const colors = {
    success: "bg-green-500",
    error: "bg-red-500",
    warning: "bg-yellow-500",
  };

  return (
    <div className={`fixed bottom-6 right-6 px-4 py-3 rounded-lg text-white text-sm font-medium shadow-lg ${colors[type]} flex items-center gap-3 z-50`}>
      {message}
      <button onClick={onClose} className="opacity-70 hover:opacity-100 text-xs">✕</button>
    </div>
  );
}

function ConfirmModal({ message, onConfirm, onCancel }: { message: string; onConfirm: () => void; onCancel: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/40" onClick={onCancel} />
      <div className="relative bg-white rounded-xl border border-zinc-200 p-6 w-72 flex flex-col gap-4 shadow-xl">
        <p className="text-sm text-zinc-700">{message}</p>
        <div className="flex gap-2 justify-end">
          <button onClick={onCancel} className="px-3 py-1.5 text-xs font-medium rounded-md border border-zinc-200 text-zinc-600 hover:bg-zinc-50">취소</button>
          <button onClick={onConfirm} className="px-3 py-1.5 text-xs font-medium rounded-md bg-red-500 text-white hover:bg-red-600">삭제</button>
        </div>
      </div>
    </div>
  );
}

const priorityColors: Record<string, string> = {
  높음: "bg-red-100 text-red-700",
  보통: "bg-blue-100 text-blue-700",
  낮음: "bg-zinc-100 text-zinc-500",
};

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([
    { id: 1, text: "디자인 시스템 색상 정의하기", done: false, priority: "높음" },
    { id: 2, text: "타이포그래피 스케일 설정", done: true, priority: "보통" },
    { id: 3, text: "버튼 컴포넌트 구현", done: false, priority: "낮음" },
  ]);
  const [input, setInput] = useState("");
  const [priority, setPriority] = useState<Todo["priority"]>("보통");
  const [filter, setFilter] = useState<Filter>("전체");
  const [showDone, setShowDone] = useState(true);
  const [modal, setModal] = useState<number | null>(null);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" | "warning" } | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  let nextId = useRef(4);

  const showToast = (message: string, type: "success" | "error" | "warning") => {
    setToast({ message, type });
  };

  const addTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) {
      showToast("할 일을 입력해주세요", "warning");
      return;
    }
    setTodos((t) => [...t, { id: nextId.current++, text: input.trim(), done: false, priority }]);
    setInput("");
    inputRef.current?.focus();
    showToast("추가됐어요", "success");
  };

  const toggleTodo = (id: number) => {
    setTodos((t) => t.map((x) => x.id === id ? { ...x, done: !x.done } : x));
  };

  const deleteTodo = (id: number) => {
    setTodos((t) => t.filter((x) => x.id !== id));
    setModal(null);
    showToast("삭제됐어요", "error");
  };

  const clearDone = () => {
    setTodos((t) => t.filter((x) => !x.done));
    showToast("완료된 항목을 모두 지웠어요", "success");
  };

  const filters: Filter[] = ["전체", "진행중", "완료"];

  const filtered = todos.filter((t) => {
    if (!showDone && t.done) return false;
    if (filter === "진행중") return !t.done;
    if (filter === "완료") return t.done;
    return true;
  });

  const doneCount = todos.filter((t) => t.done).length;

  return (
    <div className="min-h-screen bg-zinc-50 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-zinc-200 px-6 py-4 flex items-center justify-between">
